<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\UserInvitationStatusVO;
use Civi\Lughauth\Features\Access\UserInvitation\Domain\UserInvitationStatusOptions;

trait UserInvitationStatusAttributeHolder
{
    protected UserInvitationStatusVO|UserInvitationStatusOptions|null $status = null;
    protected bool $statusAssigned = false;

    public function getStatusOrCurrent(?UserInvitationStatusVO $status): ?UserInvitationStatusVO
    {
        return $this->statusAssigned ? ($this->status === null ? null : UserInvitationStatusVO::from($this->status)) : $status;
    }
    public function statusTryBuildInitial(ConstraintFailList $error): ?UserInvitationStatusVO
    {
        return  UserInvitationStatusVO::tryFrom($this->statusAssigned ? $this->status : null, $error);
    }
    public function status(UserInvitationStatusVO|UserInvitationStatusOptions|null $status): static
    {
        $this->status = $status;
        $this->statusAssigned = true;
        return $this;
    }
    public function getStatus(): ?UserInvitationStatusOptions
    {
        return $this->status instanceof UserInvitationStatusVO ? $this->status->value() : $this->status;
    }
    public function isStatusAssigned(): bool
    {
        return $this->statusAssigned;
    }
    public function writeStatusTo(mixed $att): void
    {
        if ($this->statusAssigned) {
            $att->status($this->status);
        }
    }
    public function readStatusFrom(mixed $att): void
    {
        if ($att->isStatusAssigned()) {
            $status = $att->getStatus();
            $this->status($status);
        }
    }
    public function unsetStatus(): static
    {
        $this->statusAssigned = false;
        return $this;
    }
    protected function withDefaultStatus(): void
    {
    }
    protected function withAssertedStatusRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->statusAssigned = $this->statusAssigned) {
            $value->status = UserInvitationStatusVO::tryFrom($this->status, $errorsList);
        }
    }
}
